"""
Task 010 — Simple filter expression evaluator

Implements a recursive-descent parser for filter expressions with:
  OR < AND < NOT precedence, parentheses, comparisons of fields vs values.
"""

import re
from typing import List, Tuple, Any


# ---------------------------------------------------------------------------
# Tokeniser
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
    \s*                          # skip leading whitespace
    (?:
        (>=|<=|==|!=|>|<)        # operators (multi-char first)
      | ([A-Za-z_][A-Za-z0-9_]*) # identifier or keyword
      | (-?\d+\.\d*|-?\d*\.\d+|-?\d+)  # number (int or float)
      | '([^']*)'                # single-quoted string (group 4 = content)
      | (\()                     # left paren
      | (\))                     # right paren
    )
    """,
    re.VERBOSE,
)


def _tokenize(expr: str) -> List[Tuple[str, Any]]:
    """
    Return a list of (type, value) tokens.
    Types: 'OP', 'IDENT', 'NUMBER', 'STRING', 'LPAREN', 'RPAREN'
    Keywords AND, OR, NOT are returned as ('KW', 'AND'/'OR'/'NOT').
    """
    tokens = []
    pos = 0
    while pos < len(expr):
        # Skip whitespace
        m = re.match(r'\s+', expr[pos:])
        if m:
            pos += m.end()
            continue
        if pos >= len(expr):
            break
        m = _TOKEN_RE.match(expr, pos)
        if m is None or m.start() != pos:
            raise ValueError(f"Unexpected character at position {pos}: {expr[pos]!r}")
        op, ident, number, string, lparen, rparen = m.groups()
        if op is not None:
            tokens.append(('OP', op))
        elif ident is not None:
            if ident in ('AND', 'OR', 'NOT'):
                tokens.append(('KW', ident))
            else:
                tokens.append(('IDENT', ident))
        elif number is not None:
            # Convert to int or float
            if '.' in number:
                tokens.append(('NUMBER', float(number)))
            else:
                tokens.append(('NUMBER', int(number)))
        elif string is not None:
            tokens.append(('STRING', string))
        elif lparen is not None:
            tokens.append(('LPAREN', '('))
        elif rparen is not None:
            tokens.append(('RPAREN', ')'))
        pos = m.end()
    return tokens


# ---------------------------------------------------------------------------
# Parser (recursive descent)
# ---------------------------------------------------------------------------

class _Parser:
    def __init__(self, tokens: List[Tuple[str, Any]]):
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _consume(self):
        tok = self._tokens[self._pos]
        self._pos += 1
        return tok

    def _expect(self, ttype, tval=None):
        tok = self._peek()
        if tok is None:
            raise ValueError(f"Unexpected end of expression; expected {ttype!r}")
        if tok[0] != ttype or (tval is not None and tok[1] != tval):
            raise ValueError(f"Expected {ttype!r}{' ' + repr(tval) if tval else ''}, got {tok!r}")
        return self._consume()

    def parse_expr(self):
        node = self._parse_or()
        if self._peek() is not None:
            raise ValueError(f"Unexpected token at end: {self._peek()!r}")
        return node

    def _parse_or(self):
        left = self._parse_and()
        while self._peek() == ('KW', 'OR'):
            self._consume()
            right = self._parse_and()
            left = ('OR', left, right)
        return left

    def _parse_and(self):
        left = self._parse_not()
        while self._peek() == ('KW', 'AND'):
            self._consume()
            right = self._parse_not()
            left = ('AND', left, right)
        return left

    def _parse_not(self):
        if self._peek() == ('KW', 'NOT'):
            self._consume()
            operand = self._parse_not()
            return ('NOT', operand)
        return self._parse_comparison()

    def _parse_comparison(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("Unexpected end of expression in comparison/atom")
        # Parenthesised sub-expression
        if tok[0] == 'LPAREN':
            self._consume()
            node = self._parse_or()
            self._expect('RPAREN', ')')
            return node
        # Must be field op value
        if tok[0] != 'IDENT':
            raise ValueError(f"Expected field name or '(', got {tok!r}")
        field_tok = self._consume()
        field = field_tok[1]
        op_tok = self._peek()
        if op_tok is None or op_tok[0] != 'OP':
            raise ValueError(f"Expected comparison operator after field {field!r}, got {op_tok!r}")
        op = self._consume()[1]
        val_tok = self._peek()
        if val_tok is None or val_tok[0] not in ('NUMBER', 'STRING'):
            raise ValueError(f"Expected value after operator {op!r}, got {val_tok!r}")
        val = self._consume()[1]
        return ('CMP', field, op, val)


# ---------------------------------------------------------------------------
# Evaluator
# ---------------------------------------------------------------------------

def _eval_node(node, record: dict) -> bool:
    kind = node[0]
    if kind == 'OR':
        return _eval_node(node[1], record) or _eval_node(node[2], record)
    if kind == 'AND':
        return _eval_node(node[1], record) and _eval_node(node[2], record)
    if kind == 'NOT':
        return not _eval_node(node[1], record)
    if kind == 'CMP':
        _, field, op, value = node
        if field not in record:
            raise KeyError(field)
        field_val = record[field]
        # Type check
        if isinstance(value, (int, float)):
            if not isinstance(field_val, (int, float)):
                raise TypeError(
                    f"Cannot compare {type(field_val).__name__} with numeric value"
                )
        elif isinstance(value, str):
            if not isinstance(field_val, str):
                raise TypeError(
                    f"Cannot compare {type(field_val).__name__} with string value"
                )
        # Perform comparison
        if op == '==':
            return field_val == value
        if op == '!=':
            return field_val != value
        if op == '>':
            return field_val > value
        if op == '<':
            return field_val < value
        if op == '>=':
            return field_val >= value
        if op == '<=':
            return field_val <= value
        raise ValueError(f"Unknown operator {op!r}")
    raise ValueError(f"Unknown AST node type {kind!r}")


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def evaluate(expr: str, record: dict) -> bool:
    """
    Parse and evaluate a simple filter expression against a single record.

    Returns True if the record matches the expression.

    Raises:
        ValueError: on syntax errors.
        KeyError: if a referenced field is not in record.
        TypeError: if comparison types don't match.
    """
    tokens = _tokenize(expr.strip())
    if not tokens:
        raise ValueError("Empty expression")
    parser = _Parser(tokens)
    ast = parser.parse_expr()
    return _eval_node(ast, record)
